interface Format {
    default String media() { return "text/plain"; }
    static boolean supported(String value) { return "text/plain".equals(value); }
}
class TextFormat implements Format {}
public class InterfaceMethodKindsDemo {
    public static void main(String[] args) {
        System.out.println(new TextFormat().media() + " " + Format.supported("text/plain"));
    }
}
